class BaseA {};
class BaseB {
    int padding;
public:
    virtual void v_func() = 0;
};

class Derived : public BaseA, public BaseB {
public:
    void v_func() override {}
};

// Pmf must store VTable index (for virtual)
// AND 'this' adjustment delta (for multiple inheritance).
typedef void (Derived::*Pmf)();

Pmf p = &Derived::v_func;

// Pmf implementation requires struct { long offset_or_index; int delta; };
